package com.example.rokidkeyboardbridge;
import android.content.*;import android.util.AtomicFile;import org.json.*;import java.io.*;import java.nio.charset.StandardCharsets;
/** Durable log delivery only. Never queues or repeats an AI request. */
final class AnswerOutbox {
 static AtomicFile file(Context c){return new AtomicFile(new File(c.getFilesDir(),"answer-outbox-v1.gcm"));}
 static synchronized JSONArray read(Context c)throws Exception{try{if(file(c).getBaseFile().length()>32*1024*1024)throw new IOException("回答の保存容量を確認してください");return new JSONArray(new String(DeviceSecrets.photos().decrypt(file(c).readFully()),StandardCharsets.UTF_8));}catch(FileNotFoundException absent){return new JSONArray();}}
 static void write(Context c,JSONArray rows)throws Exception{byte[] bytes=rows.toString().getBytes(StandardCharsets.UTF_8);if(bytes.length>16*1024*1024)throw new IOException("回答の転送待ち容量がいっぱいです");AtomicFile f=file(c);FileOutputStream out=null;try{out=f.startWrite();out.write(DeviceSecrets.photos().encrypt(bytes));f.finishWrite(out);}catch(Exception e){if(out!=null)f.failWrite(out);throw e;}}
 static boolean eligible(String kind){return kind!=null&&kind.matches("ユーザー|ユーザー音声|Gemini|直接回答|User|Assistant");}
 static String hash(String text)throws Exception{byte[] digest=java.security.MessageDigest.getInstance("SHA-256").digest(text.getBytes(StandardCharsets.UTF_8));StringBuilder b=new StringBuilder();for(byte n:digest)b.append(String.format(java.util.Locale.ROOT,"%02x",n&255));return b.toString();}
 static JSONObject record(String kind,String message,String request,long at,boolean legacy)throws Exception{if(kind.equals("Assistant"))kind="Gemini";if(kind.equals("User"))kind="ユーザー";if(!eligible(kind)||message==null||message.trim().isEmpty()||message.length()>64000||at<=0)throw new IOException("回答ログの保存条件を確認してください");String key=TrackedWebRequest.validId(request)?request:"";String id=hash((legacy?"legacy:"+at:key.isEmpty()?java.util.UUID.randomUUID().toString():key)+":"+kind+":"+message);return new JSONObject().put("id",id).put("kind",kind).put("message",message).put("requestId",key).put("time",at).put("legacy",legacy);}
 static boolean append(JSONArray rows,JSONObject row)throws Exception{for(int i=0;i<rows.length();i++)if(row.getString("id").equals(rows.getJSONObject(i).getString("id")))return false;if(rows.length()>=1000)throw new IOException("回答の転送待ちが1000件あります");rows.put(row);return true;}
 static synchronized String enqueue(Context c,String kind,String message,String request,long at,boolean legacy)throws Exception{JSONObject row=record(kind,message,request,at,legacy);JSONArray rows=read(c);if(append(rows,row))write(c,rows);return row.getString("id");}
 static synchronized void pair(Context c,String user,String answer,String request,String kind)throws Exception{JSONArray rows=read(c);long at=System.currentTimeMillis();append(rows,record("ユーザー",user,request,at,false));append(rows,record(kind,answer,request,at+1,false));write(c,rows);}
 static synchronized void acknowledge(Context c,String id)throws Exception{JSONArray rows=read(c),keep=new JSONArray();for(int i=0;i<rows.length();i++)if(!id.equals(rows.getJSONObject(i).getString("id")))keep.put(rows.get(i));write(c,keep);}
 static JSONObject summary(Context c)throws Exception{try{JSONArray rows=read(c);int answers=0;for(int i=0;i<rows.length();i++)if(!rows.getJSONObject(i).getString("kind").startsWith("ユーザー"))answers++;return new JSONObject().put("pendingAnswers",answers).put("pendingLogs",rows.length()).put("readable",true);}catch(Exception e){return new JSONObject().put("readable",false);}}
 private AnswerOutbox(){}
}
